import crypto from "node:crypto";import fs from "node:fs/promises";import path from "node:path";import{validatePublicNetworkUrl}from"../../web/scripts/resource-media-discovery-lib.mjs";import{ALLOWED_RASTER_TYPES}from"../../web/scripts/resource-media-review-lib.mjs";
const[candidatePath,outputDirectory]=process.argv.slice(2);if(!candidatePath||!outputDirectory)throw new Error("Expected paths.");const TYPES=new Map([["image/avif","avif"],["image/jpeg","jpg"],["image/png","png"],["image/webp","webp"]]);
async function get(initial){let current=initial,redirects=[];for(let i=0;i<=3;i++){await validatePublicNetworkUrl(current);const r=await fetch(current,{redirect:"manual",signal:AbortSignal.timeout(10000),headers:{accept:"image/avif,image/webp,image/png,image/jpeg;q=0.9,*/*;q=0.1","user-agent":"Tessli reviewed-media evidence/1.0"}});if([301,302,303,307,308].includes(r.status)){const l=r.headers.get("location");if(!l||i===3)throw new Error("Unsafe redirect");current=new URL(l,current).toString();redirects.push(current);continue}if(!r.ok)throw new Error(`HTTP ${r.status}`);const type=(r.headers.get("content-type")||"").split(";",1)[0].trim().toLowerCase();if(!ALLOWED_RASTER_TYPES.has(type))throw new Error(`Unsupported ${type}`);const bytes=Buffer.from(await r.arrayBuffer());if(!bytes.length||bytes.length>12582912)throw new Error("Invalid size");return{bytes,type,current,redirects}}throw new Error("Redirect limit")}
const source=JSON.parse(await fs.readFile(candidatePath,"utf8"));await fs.mkdir(outputDirectory,{recursive:true});const media=[];for(const r of source.resources??[])for(const kind of["preview","favicon"]){const m=r[kind];if(!m?.url)continue;const e={resourceId:r.resourceId,resourceName:r.resourceName,canonicalUrl:r.canonicalUrl,sourcePageUrl:r.sourcePageUrl??r.canonicalUrl,kind,declaredUrl:m.url,source:m.source??"favicon",sourceProperty:m.sourceProperty??null,discoveryContentType:m.contentType};try{const x=await get(m.url),fileName=`${r.resourceId}-${kind}.${TYPES.get(x.type)}`;await fs.writeFile(path.join(outputDirectory,fileName),x.bytes);Object.assign(e,{status:"downloaded",fileName,finalUrl:x.current,redirects:x.redirects,contentType:x.type,bytes:x.bytes.length,sha256:crypto.createHash("sha256").update(x.bytes).digest("hex")})}catch(error){Object.assign(e,{status:"failed",error:error instanceof Error?error.message:"failed"})}media.push(e)}await fs.writeFile(path.join(outputDirectory,"manifest.json"),JSON.stringify({version:1,media},null,2)+"\n");console.log(JSON.stringify({downloaded:media.filter(x=>x.status==="downloaded").length,failed:media.filter(x=>x.status==="failed").length}));
